'use strict';
(function(){
 const ui={city:'tashkent',method:3,date:'',prayer:null,prayerKey:'',prayerLoading:false,prayerError:'',transit:null,transitLoading:false,transitError:'',coords:null,map:false,zoom:15,voice:null,audio:false,audioContext:null,refresh:null};
 try{const saved=JSON.parse(localStorage.getItem('baraka-day-preferences')||'{}');if(Object.hasOwn(BarakaPlaces,saved.city))ui.city=saved.city;if([1,2,3,13].includes(saved.method))ui.method=saved.method}catch{}
 const city=()=>BarakaPlaces[ui.city];
 function cityDate(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:city().timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return parts.year+'-'+parts.month+'-'+parts.day}
 function preferences(){try{localStorage.setItem('baraka-day-preferences',JSON.stringify({city:ui.city,method:ui.method}))}catch{}}
 function selectCity(){return `<label class="day-city-label">Shahar<select class="select-control" aria-label="Shahar" onchange="BarakaDay.changeCity(this.value)">${Object.entries(BarakaPlaces).map(([id,p])=>`<option value="${id}" ${id===ui.city?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`}
 function agenda(date=day()){const records=[];for(const t of state.tasks||[])if(t.date===date||(!t.done&&t.date<date))records.push({...t,type:'task',route:'tasks',overdue:t.date<date&&!t.done});for(const e of state.appointments||[])if(e.date===date||(!e.done&&e.date<date))records.push({...e,type:'appointment',route:'tasks',overdue:e.date<date&&!e.done});for(const b of state.bills)if(!b.done&&b.date<=date)records.push({...b,type:'bill',route:'bills',overdue:b.date<date});for(const d of state.debts)if(remainingDebt(d)>0&&d.date<=date)records.push({...d,amount:remainingDebt(d),type:'debt',route:'debts',overdue:d.date<date});return records.sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date)||(a.time||'99:99').localeCompare(b.time||'99:99'))}
 const typeName=r=>r.type==='task'?'Vazifa':r.type==='appointment'?(r.kind==='reminder'?'Eslatma':'Uchrashuv'):r.type==='bill'?'To‘lov':'Qarz';
 function agendaRow(r){const editable=r.type==='task'||r.type==='appointment';return `<div class="agenda-row ${r.done?'agenda-done':''}"><div class="agenda-time">${r.time||'Kun davomida'}<small>${r.overdue?'Muddati o‘tgan':typeName(r)}</small></div>${editable?`<button class="task-check ${r.done?'checked':''}" onclick="BarakaDay.toggle('${r.type}','${r.id}')" aria-label="${r.done?'Bajarilmagan deb belgilash':'Bajarildi deb belgilash'}" aria-pressed="${!!r.done}">${r.done?icon('check'):''}</button>`:`<span class="row-icon">${icon(r.type==='bill'?'calendar':'hand')}</span>`}<div class="row-info"><b>${esc(r.name)}</b><small>${r.overdue?prettyDate(r.date)+' · ':''}${esc(r.member||r.location||typeName(r))}${r.amount?' · '+cash(r.amount)+' so‘m':''}</small></div><div class="agenda-actions">${!r.done&&r.type!=='debt'?`<button class="icon-button" onclick="BarakaDay.openCall('${r.type}','${r.id}')" aria-label="Telefon qo‘ng‘irog‘i bilan eslatish" title="Telefon qo‘ng‘irog‘i">${icon('bell')}</button>`:''}${editable?`<button class="icon-button" onclick="openForm('day-${r.type}','${r.id}')" aria-label="Tahrirlash">${icon('edit')}</button><button class="icon-button" onclick="BarakaDay.remove('${r.type}','${r.id}')" aria-label="O‘chirish">${icon('trash')}</button>`:`<a class="text-button" href="#${r.route}">Ochish ↗</a>`}</div></div>`}
 function todayPage(){const items=agenda(),tasks=items.filter(r=>r.type==='task'),meetings=items.filter(r=>r.type==='appointment'&&r.kind!=='reminder'),payments=items.filter(r=>r.type==='bill'||r.type==='debt'),completed=tasks.filter(r=>r.done).length;return `<section class="day-hero"><div><p class="eyebrow">BIR JOYDA · BIR KUNLIK REJALAR</p><h2>Buguningizga tartib bering.</h2><p>Vazifalar, uchrashuvlar va to‘lovlar bir qarashda.</p><div class="day-hero-actions"><button class="primary" onclick="openForm('day-task')">${icon('plus')} Vazifa</button><button class="secondary" onclick="openForm('day-appointment')">${icon('calendar')} Uchrashuv / eslatma</button></div></div><div class="day-orb" aria-hidden="true"><span>✦</span><i></i></div></section><div class="report-stats day-summary">${[['Vazifalar',`${completed}/${tasks.length}`,'Bajarilgan / bugungi'],['Uchrashuvlar',meetings.filter(r=>!r.done).length,'Rejalashtirilgan'],['To‘lov / qarz',payments.length,'Bugun va muddati o‘tgan'],['Eslatmalar',items.filter(r=>r.kind==='reminder'&&!r.done).length,'Kundalik rejalar']].map(([label,n,foot])=>`<section class="report-stat"><small>${label}</small><b>${n}</b><em>${foot}</em></section>`).join('')}</div><div class="grid"><section class="card"><div class="card-head"><div><h2>Bugungi kun tartibi</h2><p>${prettyDate(day())} · qurilmangizning mahalliy sanasi</p></div><a class="text-button" href="#tasks">Barchasi →</a></div>${items.map(agendaRow).join('')||empty('Buguningiz uchun hali reja yo‘q','Birinchi vazifa yoki uchrashuvni qo‘shing.')}<div class="chart-note">${icon('bell')} <span>Saytdagi signal ${ui.audio?'yoqilgan':'o‘chiq'}. Telefon qo‘ng‘irog‘i alohida sozlanadi.</span><button class="text-button" onclick="BarakaDay.enableAudio()">${ui.audio?'Sinash':'Yoqish'}</button>${ui.audio?'<button class="text-button" onclick="BarakaDay.disableAudio()">O‘chirish</button>':''}</div></section><section class="card"><div class="card-head"><h2>Kundalik yordamchilar</h2>${icon('spark')}</div><a class="day-shortcut" href="#prayer"><span>☾</span><div><b>Namoz vaqtlari</b><small>${esc(city().name)} · manbadan yangilash</small></div><i>↗</i></a><a class="day-shortcut" href="#transport"><span>▣</span><div><b>Avtobus va bekatlar</b><small>Yo‘nalishlar, xarita va GPS holati</small></div><i>↗</i></a><a class="day-shortcut" href="#utilities"><span>⌂</span><div><b>Kommunal hisoblar</b><small>Abonentlar va operator ulanishi</small></div><i>↗</i></a><a class="day-shortcut" href="#calendar"><span>▦</span><div><b>Umumiy taqvim</b><small>Moliyaviy va kundalik sanalar</small></div><i>↗</i></a><button class="day-shortcut shortcut-button" onclick="BarakaDay.openVoiceSettings()"><span>☎</span><div><b>Qo‘ng‘iroqli eslatma</b><small>O‘z raqamingizga telefon qo‘ng‘irog‘i</small></div><i>↗</i></button></section></div>`}
 function tasksPage(){return `<section class="card"><div class="card-head"><div><h2>Vazifalar, uchrashuvlar va eslatmalar</h2><p>Bu yozuvlar faol oilaviy hisobdagi a’zolarga ko‘rinadi.</p></div><div class="settings-actions"><button class="secondary" onclick="openForm('day-appointment')">Uchrashuv</button><button class="primary" onclick="openForm('day-task')">＋ Vazifa</button></div></div><div class="filters"><input id="day-search" type="search" placeholder="Rejadan qidirish…" aria-label="Rejadan qidirish" oninput="BarakaDay.filterTasks()"><select id="day-filter" aria-label="Holat" onchange="BarakaDay.filterTasks()"><option value="open">Bajarilmagan</option><option value="today">Bugungi</option><option value="all">Barchasi</option><option value="done">Bajarilgan</option></select></div><div id="day-task-list"></div></section><div class="insight-banner"><div class="insight-icon">${icon('bell')}</div><div><b>Eslatish usulini tanlang</b><p>Saytdagi signal faqat sayt ochiq va ovozga ruxsat berilganida ishlaydi. Telefon qo‘ng‘irog‘i uchun tasdiqlangan raqam, operator va server kerak.</p></div><button class="text-button" onclick="BarakaDay.openVoiceSettings()">Qo‘ng‘iroq sozlamasi ↗</button></div>`}
 function filterTasks(){const search=($('#day-search')?.value||'').toLocaleLowerCase(),filter=$('#day-filter')?.value||'open',rows=[...(state.tasks||[]).map(t=>({...t,type:'task'})),...(state.appointments||[]).map(t=>({...t,type:'appointment'}))].filter(r=>r.name.toLocaleLowerCase().includes(search)&&(filter==='all'||filter==='today'&&r.date===day()||filter==='done'&&r.done||filter==='open'&&!r.done)).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'99:99').localeCompare(b.time||'99:99'));if($('#day-task-list'))$('#day-task-list').innerHTML=rows.map(r=>agendaRow({...r,overdue:!r.done&&r.date<day()})).join('')||empty('Mos reja topilmadi','Filtrni o‘zgartiring yoki yangi reja qo‘shing.')}
 function form(type,id){if(!['day-task','day-appointment','day-call'].includes(type))return null;if(type==='day-call'){return{title:'Telefon orqali eslatish',html:field('Qo‘ng‘iroq vaqti (qurilmangiz vaqti)','callTime','datetime-local','','required')+'<div class="form-note">Faqat o‘z hisobingizga biriktirilgan raqamga qo‘ng‘iroq qilinadi. Operator tarifi bo‘yicha haq olinishi mumkin. Eng ko‘pi 3 ta qo‘ng‘iroq / 24 soat.</div>'}}const list=type==='day-task'?'tasks':'appointments',d=state[list]?.find(x=>x.id===id)||{};return{title:type==='day-task'?(id?'Vazifani tahrirlash':'Yangi vazifa'):(id?'Rejani tahrirlash':'Uchrashuv / eslatma'),html:nameField('Nomi',d.name||'',100)+(type==='day-appointment'?select('Turi','kind',[['meeting','Uchrashuv'],['reminder','Oddiy eslatma']],d.kind||'meeting'):'')+`<div class="form-grid">${dateField('Sana',d.date||day())}${field('Vaqt '+(type==='day-task'?'(ixtiyoriy)':''),'time','time',d.time||'',type==='day-task'?'':'required')}</div>`+(type==='day-task'?select('Kim uchun?','member',state.members.map(m=>[m,m]),d.member||state.members[0])+select('Muhimlik','priority',[['normal','Oddiy'],['high','Muhim'],['low','Shoshilinch emas']],d.priority||'normal'):field('Joy (ixtiyoriy)','location','text',d.location||'','maxlength="150"'))+select('Ovozli signal','remindMinutes',[[0,'O‘z vaqtida'],[5,'5 daqiqa oldin'],[15,'15 daqiqa oldin'],[30,'30 daqiqa oldin'],[60,'1 soat oldin']],d.remindMinutes||0)+'<p class="section-text">Vaqt qurilmangiz soatiga ko‘ra. Saytdagi ovoz alohida yoqiladi; telefon qo‘ng‘irog‘i har bir reja uchun alohida belgilanadi.</p>'}}
 function commit(type,id,d){if(!['day-task','day-appointment'].includes(type))return false;const key=type==='day-task'?'tasks':'appointments',old=state[key]?.find(t=>t.id===id),record={...d,id:id||uid(),done:old?.done||false,remindMinutes:Number(d.remindMinutes||0)};const records=id?state[key].map(x=>x.id===id?record:x):[...(state[key]||[]),record];state=normalize({...state,[key]:records});return true}
 function toggle(type,id){const key=type==='task'?'tasks':'appointments',record=state[key]?.find(x=>x.id===id);if(record){record.done=!record.done;save(record.done?'Bajarildi ✓':'Reja qayta ochildi')}}
 function remove(type,id){const key=type==='task'?'tasks':'appointments';confirmAction('Reja o‘chirilsinmi?','<p class="section-text">Tegishli telefon eslatmasi keyingi server tekshiruvida bekor qilinadi.</p>',()=>{state[key]=state[key].filter(x=>x.id!==id);save()})}
 function changeCity(value){if(!Object.hasOwn(BarakaPlaces,value))return;ui.city=value;ui.coords=null;ui.prayer=null;ui.transit=null;ui.prayerError='';ui.transitError='';preferences();render()}
 function prayerPage(){return `<section class="card"><div class="card-head"><div><h2>Namoz vaqtlari</h2><p>Manba: AlAdhan · hisoblangan vaqtlar · hanafiy asr hisobi</p></div>${selectCity()}</div><div class="filters"><input class="select-control" id="prayer-date" type="date" aria-label="Namoz sanasi" value="${ui.date||cityDate()}" onchange="BarakaDay.setPrayerDate(this.value)"><select class="select-control" aria-label="Hisoblash usuli" onchange="BarakaDay.setMethod(this.value)">${[[3,'Muslim World League'],[1,'Karachi'],[2,'ISNA'],[13,'Turkiya Diyanet']].map(([v,n])=>`<option value="${v}" ${ui.method===v?'selected':''}>${n}</option>`).join('')}</select><button class="secondary" onclick="BarakaDay.loadPrayer()">Yangilash ↻</button></div><div id="prayer-result">${prayerResult()}</div><div class="form-note">Bu hisoblangan jadval. Mahalliy masjid yoki O‘zbekiston musulmonlari idorasi tasdiqlagan jadval bilan farq qilishi mumkin. Shahar va hisoblash usulini tekshiring. Internet bo‘lmasa vaqtlar taxmin qilib chiqarilmaydi.</div><a class="text-button section-gap" href="https://aladhan.com/prayer-times-api" target="_blank" rel="noopener noreferrer">Manba va hisoblash haqida ↗</a></section>`}
 function prayerResult(){if(ui.prayerLoading)return empty('Namoz vaqtlari yuklanmoqda…');if(ui.prayerError)return empty(esc(ui.prayerError),'Server va internet aloqasini tekshirib qayta urinib ko‘ring.');const p=ui.prayer;if(!p||p.cityId!==ui.city||p.date!==(ui.date||cityDate())||p.method!==ui.method)return empty('Jadvalni manbadan yuklang','Shahar, sana va usulni tanlab “Yangilash”ni bosing.');return `<div class="prayer-heading"><span>☾ ${esc(p.city)}</span><span>${prettyDate(p.date)} · ${esc(p.timezone)}</span></div><div class="prayer-grid">${[['Fajr','Bomdod','☾'],['Sunrise','Quyosh','☀'],['Dhuhr','Peshin','☀'],['Asr','Asr','◒'],['Maghrib','Shom','◔'],['Isha','Xufton','☾']].map(([key,label,symbol])=>`<div class="prayer-time"><span>${symbol}</span><small>${label}</small><b>${esc(p.timings[key])}</b></div>`).join('')}</div><p class="section-text">Manbadan olindi: ${new Date(p.fetchedAt).toLocaleString('uz-UZ')} · Usul #${p.method}</p>`}
 async function loadPrayer(){if(ui.prayerLoading)return;const key=ui.city+':'+(ui.date||cityDate())+':'+ui.method;ui.prayerKey=key;ui.prayerLoading=true;ui.prayerError='';if($('#prayer-result'))$('#prayer-result').innerHTML=prayerResult();try{if(!globalThis.barakaCloud?.request)throw Error('Namoz vaqtlari uchun saytni npm start orqali oching.');const data=await globalThis.barakaCloud.request('/api/prayer-times?'+new URLSearchParams({city:ui.city,date:ui.date||cityDate(),method:ui.method}));if(key===ui.city+':'+(ui.date||cityDate())+':'+ui.method)ui.prayer=data}catch(e){ui.prayerError=e.message}finally{ui.prayerLoading=false;if($('#prayer-result')&&page==='prayer')$('#prayer-result').innerHTML=prayerResult()}}
 function setPrayerDate(value){ui.date=value;ui.prayer=null;ui.prayerError='';render()}
 function setMethod(value){ui.method=Number(value);ui.prayer=null;ui.prayerError='';preferences();render()}
 function transportPage(){return `<section class="card"><div class="card-head"><div><h2>Avtobuslar va bekatlar</h2><p>Bekatlar xaritasi va mavjud bo‘lsa operator GPS ma’lumoti</p></div>${selectCity()}</div><div class="day-transport-controls"><button class="primary" onclick="BarakaDay.loadTransit()">Bekatlarni ko‘rsatish</button><button class="secondary" onclick="BarakaDay.locate()">${icon('target')} Menga yaqin</button><span>${ui.coords?'Qurilmadan bir martalik joylashuv olindi':'Shahar markazi bo‘yicha qidiriladi'}</span></div><p class="section-text">“Menga yaqin” tugmasi joylashuvingizga ruxsat so‘raydi. Koordinata bekatlarni qidirish uchun xarita xizmatiga yuboriladi; oilaviy hisobda saqlanmaydi.</p><div id="transit-result">${transitResult()}</div></section><div class="form-note">GPS nuqtasining o‘zi aniq kelish vaqtini bermaydi. ETA faqat operator taqdim etgan yangi prognozdan olinadi. 2 daqiqadan eski GPS belgisi jonli xaritada ko‘rsatilmaydi.</div>`}
 function transitResult(){if(ui.transitLoading)return empty('Transport ma’lumotlari yuklanmoqda…');if(ui.transitError)return empty(esc(ui.transitError),'Qidirishni qayta bajaring. Jonli ma’lumot o‘rniga soxta avtobus belgisi ko‘rsatilmaydi.');const t=ui.transit;if(!t||t.cityId!==ui.city)return empty('Yaqin bekatlarni qidiring','Jonli GPS operatori ulanmagan bo‘lsa, faqat xarita ma’lumoti ko‘rsatiladi.');return `<div class="transit-source"><span class="badge ${t.live?'good':'warn'}">${t.live?'Operator GPS ulangan':'Jonli GPS ulanmagan'}</span><small>${esc(t.source)} · ${new Date(t.fetchedAt).toLocaleString('uz-UZ')}</small></div>${t.notice?`<div class="chart-note">${esc(t.notice)}</div>`:''}<div class="transit-map" id="bus-map">${ui.map?mapHTML():`<div class="map-placeholder">${icon('grid')}<b>Bekatlar xaritasi</b><p>Xaritani ochishda OpenStreetMap rasmlari yuklanadi.</p><button class="secondary" onclick="BarakaDay.showMap()">Xaritani ochish ↗</button></div>`}</div><div class="filters section-gap"><input type="search" id="bus-search" aria-label="Bekat yoki yo‘nalishni qidirish" placeholder="Bekat yoki yo‘nalish…" oninput="BarakaDay.filterTransit()"><button class="text-button" onclick="BarakaDay.loadTransit()">Yangilash ↻</button></div><div class="grid equal-grid"><div><h3>Bekatlar · ${t.stops.length}</h3><div id="bus-stop-list">${stopRows(t.stops)}</div></div><div><h3>Yo‘nalishlar · ${t.routes.length}</h3><div id="bus-route-list">${routeRows(t.routes)}</div></div></div>`}
 function stopRows(stops){return stops.slice(0,80).map(s=>{const arrivals=ui.transit.arrivals.filter(a=>a.stopId===s.id&&Date.now()-a.updatedAt<120000).sort((a,b)=>a.expectedAt-b.expectedAt).slice(0,4);return `<div class="row"><div class="row-icon">▣</div><div class="row-info"><b>${esc(s.name)}</b><small>${s.lat.toFixed(4)}, ${s.lon.toFixed(4)}</small>${arrivals.length?arrivals.map(a=>`<span class="badge good">${esc(ui.transit.routes.find(r=>r.id===a.routeId)?.ref||'Avtobus')} · ${Math.max(0,Math.ceil((a.expectedAt-Date.now())/60000))} daqiqa</span>`).join(''):'<span class="badge">Kelish vaqti mavjud emas</span>'}</div><a class="text-button" href="https://www.openstreetmap.org/?mlat=${s.lat}&mlon=${s.lon}#map=17/${s.lat}/${s.lon}" target="_blank" rel="noopener noreferrer">Xarita ↗</a></div>`}).join('')||empty('Bekat topilmadi','Xarita ma’lumotlari bu hududda to‘liq bo‘lmasligi mumkin.')}
 function routeRows(routes){return routes.slice(0,80).map(r=>`<div class="row"><span class="bus-ref">${esc(r.ref)}</span><div class="row-info"><b>${esc(r.name)}</b><small>${ui.transit.live?ui.transit.vehicles.filter(v=>v.routeId===r.id&&!v.stale&&Date.now()-v.updatedAt<120000).length+' ta yangi GPS nuqta':'Jonli joylashuv mavjud emas'}</small></div></div>`).join('')||empty('Yaqin yo‘nalish ma’lumoti topilmadi','Bu avtobus qatnamaydi degani emas.')}
 function tileXY(lat,lon,z){const n=2**z,r=lat*Math.PI/180;return{x:(lon+180)/360*n,y:(1-Math.log(Math.tan(r)+1/Math.cos(r))/Math.PI)/2*n}}
 function mapHTML(){const t=ui.transit,c=t.center,z=ui.zoom,p=tileXY(c.lat,c.lon,z);let tiles='';for(let x=Math.floor(p.x)-1;x<=Math.floor(p.x)+1;x++)for(let y=Math.floor(p.y)-1;y<=Math.floor(p.y)+1;y++)tiles+=`<img class="map-tile" referrerpolicy="strict-origin-when-cross-origin" alt="" src="https://tile.openstreetmap.org/${z}/${x}/${y}.png" style="left:${(x-p.x)*256}px;top:${(y-p.y)*256}px" width="256" height="256" loading="lazy">`;const pins=[...t.stops.map(s=>({...s,kind:'stop'})),...t.vehicles.filter(v=>!v.stale&&Date.now()-v.updatedAt<120000).map(v=>({...v,name:t.routes.find(r=>r.id===v.routeId)?.ref||'Avtobus',kind:'bus'}))];return `<div class="map-canvas">${tiles}${pins.map(s=>{const q=tileXY(s.lat,s.lon,z);return `<span class="map-pin ${s.kind==='bus'?'map-bus':''}" style="left:${(q.x-p.x)*256}px;top:${(q.y-p.y)*256}px" title="${esc(s.name)}" aria-label="${esc(s.name)}">${s.kind==='bus'?esc(s.name):'▣'}</span>`}).join('')}<span class="map-center" aria-label="Qidirish markazi"></span></div><div class="map-zoom"><button class="icon-button" aria-label="Yaqinlashtirish" onclick="BarakaDay.zoomMap(1)">＋</button><button class="icon-button" aria-label="Uzoqlashtirish" onclick="BarakaDay.zoomMap(-1)">−</button></div><a class="map-credit" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap contributors</a>`}
 function showMap(){ui.map=true;if($('#bus-map'))$('#bus-map').innerHTML=mapHTML()}
 function zoomMap(n){ui.zoom=Math.max(12,Math.min(17,ui.zoom+n));showMap()}
 function filterTransit(){const q=($('#bus-search').value||'').toLocaleLowerCase();$('#bus-stop-list').innerHTML=stopRows(ui.transit.stops.filter(s=>s.name.toLocaleLowerCase().includes(q)));$('#bus-route-list').innerHTML=routeRows(ui.transit.routes.filter(r=>(r.ref+' '+r.name).toLocaleLowerCase().includes(q)))}
 async function loadTransit(silent=false){if(ui.transitLoading)return;ui.lastTransitRequest=Date.now();ui.transitLoading=true;ui.transitError='';const cityId=ui.city;if(!silent&&$('#transit-result'))$('#transit-result').innerHTML=transitResult();try{if(!globalThis.barakaCloud?.request)throw Error('Transport uchun saytni npm start orqali oching.');const params=new URLSearchParams({city:cityId});if(ui.coords){params.set('lat',ui.coords.lat);params.set('lon',ui.coords.lon)}const result=await globalThis.barakaCloud.request('/api/transit?'+params);if(ui.city===cityId)ui.transit=result}catch(e){ui.transitError=e.message}finally{ui.transitLoading=false;if(page==='transport'&&$('#transit-result'))$('#transit-result').innerHTML=transitResult()}}
 function locate(){if(!navigator.geolocation){toast('Brauzer joylashuvni qo‘llab-quvvatlamaydi.');return}navigator.geolocation.getCurrentPosition(position=>{ui.coords={lat:position.coords.latitude,lon:position.coords.longitude};if(Math.abs(ui.coords.lat-city().lat)>0.4||Math.abs(ui.coords.lon-city().lon)>0.6){ui.coords=null;toast('GPS boshqa shaharni ko‘rsatmoqda. Avval mos shaharni tanlang.');return}loadTransit()},()=>toast('Joylashuv olinmadi. Shahar markazidan qidirishingiz mumkin.'),{enableHighAccuracy:false,timeout:10000,maximumAge:60000})}
 async function voiceInfo(){if(!globalThis.barakaCloud?.user)throw Error('Telefon eslatmasi uchun avval hisobga kiring.');ui.voice=await globalThis.barakaCloud.request('/api/voice/settings');return ui.voice}
 async function openVoiceSettings(){try{const v=await voiceInfo();const labels={pending:'Rejalashtirilgan',dispatching:'Operatorga yuborilmoqda',queued:'Operator qabul qilgan',initiated:'Boshlangan',ringing:'Jiringlamoqda','in-progress':'Javob berilgan',completed:'Yakunlangan',busy:'Raqam band',failed:'Bajarilmadi','no-answer':'Javob bo‘lmadi',canceled:'Bekor qilingan',unknown:'Holati noma’lum',missed:'Vaqti o‘tib ketgan'};formType='day-voice-view';setModal('Telefon qo‘ng‘irog‘i orqali eslatma',`<div class="form-note">${v.configured?'Qo‘ng‘iroq operatori sozlangan.':'Qo‘ng‘iroq operatori hali ulanmagan.'}<br>${v.eligible?'Sizning tasdiqlangan raqamingiz: '+esc(v.number):'Sizga tegishli tasdiqlangan raqam hali biriktirilmagan.'}<br>Qo‘ng‘iroq xizmati pullik bo‘lishi mumkin. Umumiy eslatma aytiladi, rejangiz mazmuni o‘qilmaydi.</div>${v.configured&&v.eligible?`<button type="button" class="${v.consent?'danger-button':'primary'} section-gap" onclick="BarakaDay.voiceConsent(${!v.consent})">${v.consent?'Qo‘ng‘iroqlarni o‘chirish':'O‘z raqamimga qo‘ng‘iroq eslatmalariga roziman'}</button>`:''}<div class="section-gap">${v.jobs.filter(j=>j.householdId===globalThis.barakaCloud.household.id).reverse().map(j=>`<div class="row"><div class="row-info"><b>${new Date(j.dueAt).toLocaleString('uz-UZ')}</b><small>${labels[j.status]||esc(j.status)}</small></div>${j.status==='pending'?`<button type="button" class="text-button" onclick="BarakaDay.cancelCall('${j.id}')">Bekor qilish</button>`:''}</div>`).join('')||'<p class="section-text">Hali telefon qo‘ng‘irog‘i rejalashtirilmagan.</p>'}</div>`,false)}catch(e){toast(e.message)}}
 async function voiceConsent(enabled){try{await globalThis.barakaCloud.request('/api/voice/consent','POST',{enabled});await openVoiceSettings()}catch(e){toast(e.message)}}
 let callTarget=null;
 async function openCall(type,id){try{await globalThis.barakaCloud?.flush();const v=await voiceInfo();if(!v.configured||!v.eligible||!v.consent){await openVoiceSettings();return}callTarget={type,id};openForm('day-call');const record=(type==='task'?state.tasks:type==='appointment'?state.appointments:state.bills).find(r=>r.id===id);const value=record.date+'T'+(record.time||'09:00');$('#fields input[name=callTime]').value=value}catch(e){toast(e.message)}}
 async function submitCall(d){const button=$('#save-button');if(button.disabled)return;button.disabled=true;try{if(!callTarget)throw Error('Eslatma tanlanmagan.');const dueAt=new Date(d.callTime).getTime();await globalThis.barakaCloud.request('/api/voice/schedule','POST',{targetType:callTarget.type,targetId:callTarget.id,dueAt});closeModal();toast('Qo‘ng‘iroq rejalashtirildi. Hali qo‘ng‘iroq qilinmadi.')}catch(e){$('#form-error').textContent=e.message}finally{button.disabled=false}}
 async function cancelCall(id){try{await globalThis.barakaCloud.request('/api/voice/cancel','POST',{id});openVoiceSettings()}catch(e){toast(e.message)}}
 function beep(){const context=ui.audioContext;if(!context)return;context.resume();for(let i=0;i<3;i++){const osc=context.createOscillator(),gain=context.createGain(),time=context.currentTime+i*.45;osc.type='sine';osc.frequency.value=660;gain.gain.setValueAtTime(0,time);gain.gain.linearRampToValueAtTime(.12,time+.03);gain.gain.linearRampToValueAtTime(0,time+.3);osc.connect(gain);gain.connect(context.destination);osc.start(time);osc.stop(time+.32)}}
 function enableAudio(){const Context=window.AudioContext||window.webkitAudioContext;if(!Context){toast('Brauzer ovozli signalni qo‘llab-quvvatlamaydi.');return}try{ui.audioContext=ui.audioContext||new Context();ui.audio=true;beep();toast('Ovozli signal yoqildi. Sayt ochiq tursin.');if(page==='today')render()}catch{toast('Ovozga ruxsat berilmadi.')}}
 function disableAudio(){ui.audio=false;ui.audioContext?.suspend();toast('Saytdagi ovozli signal o‘chirildi.');if(page==='today')render()}
 function checkAlarms(){if(!ui.audio)return;const now=Date.now();for(const [type,records]of [['task',state.tasks||[]],['appointment',state.appointments||[]]])for(const r of records){if(r.done||!r.time)continue;const at=new Date(r.date+'T'+r.time).getTime()-(r.remindMinutes||0)*60000;if(at>now||now-at>60000)continue;const key='baraka-alarm-'+(globalThis.barakaCloud?.household?.id||'guest')+'-'+type+'-'+r.id+'-'+at;try{if(localStorage.getItem(key))continue;localStorage.setItem(key,'1')}catch{}beep();toast('Eslatma: '+r.name)}}
 function calendarEvents(start,end){return [...(state.tasks||[]).filter(r=>!r.done).map(r=>({...r,kind:'task'})),...(state.appointments||[]).filter(r=>!r.done).map(r=>({...r,kind:'appointment'}))].filter(r=>r.date>=start&&r.date<=end).map(r=>({date:r.date,title:r.name+(r.time?' · '+r.time:''),kind:r.kind,amount:null,route:'tasks'}))}
 function afterRender(){if(page==='tasks')filterTasks()}
 const titles={today:['Buguningiz bir joyda ✦','Vazifalar, uchrashuvlar, to‘lovlar va eslatmalar.'],tasks:['Kuningizni rejalashtiring','Muhim ishlar va uchrashuvlarni unutmang.'],prayer:['Namoz vaqtlari','Shahar va hisoblash usuli bilan namoz jadvali.'],transport:['Yo‘lda ham xotirjam','Avtobus yo‘nalishlari, yaqin bekatlar va GPS holati.']};
 globalThis.BarakaDay={titles,views:{today:todayPage,tasks:tasksPage,prayer:prayerPage,transport:transportPage},agenda,form,commit,toggle,remove,changeCity,setPrayerDate,setMethod,loadPrayer,loadTransit,locate,filterTasks,filterTransit,showMap,zoomMap,openVoiceSettings,voiceConsent,openCall,submitCall,cancelCall,enableAudio,disableAudio,checkAlarms,calendarEvents,afterRender,ui};
 if(typeof setInterval==='function')setInterval(()=>{checkAlarms();if(ui.transit?.live&&page==='transport'&&!document.hidden&&Date.now()-(ui.lastTransitRequest||0)>=30000)loadTransit(true)},15000);
 if(typeof document.addEventListener==='function')document.addEventListener('visibilitychange',()=>{if(!document.hidden&&ui.transit?.live&&page==='transport')loadTransit(true)});
})();
